-- Restore Domination Point (map 1102, scenario 201).
-- Spawn and object data were ported read-only from Legends of Azeroth
-- Pandaria 5.4.8 (build 18414); scripts were adapted to Legion 7.3.5.
-- Legion build 26972 DB2 confirms the Horde scenario, seven criteria trees, and LFG entry 595.
START TRANSACTION;

-- Replace any partial population with the coherent MoP scenario population.
DELETE `ca` FROM `creature_addon` `ca` INNER JOIN `creature` `c` ON `c`.`guid`=`ca`.`guid` WHERE `c`.`map`=1102;
DELETE `wp` FROM `waypoint_data` `wp` INNER JOIN `creature` `c` ON `c`.`guid`=`wp`.`id` WHERE `c`.`map`=1102;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`memberGUID` WHERE `c`.`map`=1102;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`leaderGUID` WHERE `c`.`map`=1102;
DELETE `gec` FROM `game_event_creature` `gec` INNER JOIN `creature` `c` ON `c`.`guid`=`gec`.`guid` WHERE `c`.`map`=1102;
DELETE `pc` FROM `pool_creature` `pc` INNER JOIN `creature` `c` ON `c`.`guid`=`pc`.`guid` WHERE `c`.`map`=1102;
DELETE `geg` FROM `game_event_gameobject` `geg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`geg`.`guid` WHERE `go`.`map`=1102;
DELETE `pg` FROM `pool_gameobject` `pg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`pg`.`guid` WHERE `go`.`map`=1102;
DELETE FROM `creature` WHERE `map`=1102;
DELETE FROM `gameobject` WHERE `map`=1102;



-- Bind the six stage interaction NPCs.
UPDATE `creature_template` SET `ScriptName`='npc_domination_point_interaction', `npcflag`=`npcflag`|1 WHERE `entry` IN (68997,68998,68999,69000,69001,69002);

-- The three weapon markers are shared with Lion's Landing. Their existing generic
-- spell-click handler uses the same data slots in both mirrored scenarios.
UPDATE `creature_template` SET `ScriptName`='npc_lions_landing_interaction', `npcflag`=`npcflag`|16777216 WHERE `entry` IN (68884,68885,68886);
DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` IN (68884,68885,68886);

-- Restore attackable Alliance forces; imported source templates use faction 84.
UPDATE `creature_template` SET `faction`=84, `unit_flags`=0, `unit_flags2`=2048
WHERE `entry` IN (67305,67419,67420,67428,67431,67530,67550,67690,67762,67794,67811,68983,69004,69005,69006,69007,69008,69009,69020);

ON DUPLICATE KEY UPDATE `parent`=VALUES(`parent`),`script`=VALUES(`script`),`allowMount`=VALUES(`allowMount`);

DELETE FROM `scenario_data` WHERE `MapID`=1102 OR `ScenarioID`=201;

-- Enable only after all spawn, script, and scenario data is installed.
DELETE FROM `disables` WHERE `sourceType`=2 AND `entry`=1102;

COMMIT;
